        await using var held=fixture.CreateContext();await using var tx=await held.Database.BeginTransactionAsync();var id=kind switch{"account"=>s.InternalId,"profile"=>p.Id,"collection"=>a.Collection.Id,"folder"=>root.Id,_=>record.Id};var table=kind=="session"?"vault_access_session":kind;await held.Database.ExecuteSqlRawAsync(kind=="session"?"SELECT FROM cerberus.vault_access_session WHERE handle_verifier={0} FOR UPDATE":"SELECT FROM cerberus."+table+" WHERE id={0} FOR UPDATE",kind=="session"?(object)s.Verifier:id);
        var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);using var ct=new CancellationTokenSource(TimeSpan.FromSeconds(20));var pending=new FolderTrashStore(new ProfileSetup.Factory(fixture,new Signal(reached,table))).TrashAsync(new(s.Actor,s.Verifier,root.PublicId,99),ct.Token);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(pending.IsCompleted);await Past(deadline);await tx.CommitAsync();Assert.Equal("vault_access_denied",(await pending).Error);Assert.Equal(before,await Snapshot(s));
    }
