    [FunctionalTheory][InlineData("root",false)][InlineData("root",true)][InlineData("child",false)][InlineData("child",true)][InlineData("parent",false)][InlineData("parent",true)]
    public async Task GivenExhaustedOrRegressedSequenceAtDifferentCascadeStages_WhenDeleting_ThenRollbackAllContent(string stage,bool regression)
    {
        using var owner=new ProtectionFixture();using var key=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);await Folder(s,root.Id);await Profile(s,owner,key,folders:[root.PublicId]);var before=await Snapshot(s);await using var db=fixture.CreateContext();var previous=await db.Database.SqlQuery<long>($"SELECT nextval('cerberus.server_sequence') AS \"Value\"").SingleAsync();var hook=new AtWrite(stage,async()=>{await using var other=fixture.CreateContext();await other.Database.ExecuteSqlRawAsync(regression?"SELECT setval('cerberus.server_sequence',1,false)":"SELECT setval('cerberus.server_sequence',9007199254740991,true)");});try{Assert.Equal(regression?"persistence_unavailable":"revision_conflict",(await new FolderTrashStore(new ProfileSetup.Factory(fixture,hook)).TrashAsync(new(s.Actor,s.Verifier,root.PublicId,1),default)).Error);Assert.True(hook.Triggered);Assert.Equal(before,await Snapshot(s));}finally{await db.Database.ExecuteSqlInterpolatedAsync($"SELECT setval('cerberus.server_sequence',{previous},true)");}
