    [FunctionalTheory][InlineData("folder",false)][InlineData("folder",true)][InlineData("record",false)][InlineData("record",true)]
    public async Task GivenActualRecipientContentEditAndOwnerCascade_WhenCompeting_ThenOneWinnerWithoutCollectionContentLockCycle(string resource,bool trashFirst)
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();var o=await ProfileSetup.Create(fixture,owner);var s=await ProfileSetup.Create(fixture,client);var a=await AssociationSetup.Items(fixture,o);var root=await Folder(o);var record=await Record(o,root.Id);await Members(o,a.Collection,[],[root.Id]);await AssociationSetup.Grant(fixture,o,owner,s,client,a.Collection,CollectionGrantAccess.ReadWrite);var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var blocked=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);using var ct=new CancellationTokenSource(TimeSpan.FromSeconds(25));Task<VaultResult<FolderTrashDetails>> trash;Task<string?> edit;
        async Task<string?> Edit(IDbContextFactory<AppDbContext> f){return resource=="folder"?(await new FolderUpdateStore(f).UpdateAsync(new(s.Actor,s.Verifier,root.PublicId,new(1,ProfileSetup.Envelope(),DateTimeOffset.UnixEpoch)),ct.Token)).Error:(await new RecordUpdateStore(f).UpdateAsync(new(s.Actor,s.Verifier,record.PublicId,new(1,ProfileSetup.Envelope(),DateTimeOffset.UnixEpoch)),ct.Token)).Error;}
        if(trashFirst){trash=new FolderTrashStore(new ProfileSetup.Factory(fixture,new BeforeContent(async()=>{reached.TrySetResult();await release.Task.WaitAsync(ct.Token);}))).TrashAsync(new(o.Actor,o.Verifier,root.PublicId,1),ct.Token);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));edit=Edit(new ProfileSetup.Factory(fixture,new Signal(blocked,"collection")));}
        else{edit=Edit(new ProfileSetup.Factory(fixture,new PauseUpdate(async()=>{reached.TrySetResult();await release.Task.WaitAsync(ct.Token);})));await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));trash=new FolderTrashStore(new ProfileSetup.Factory(fixture,new Signal(blocked,"collection"))).TrashAsync(new(o.Actor,o.Verifier,root.PublicId,1),ct.Token);}
        try{await blocked.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(trashFirst?edit.IsCompleted:trash.IsCompleted);}finally{release.TrySetResult();}await Task.WhenAll(trash,edit);
        if(trashFirst){Assert.Null(trash.Result.Error);Assert.Equal("not_found",edit.Result);}else{Assert.Null(edit.Result);Assert.Equal("revision_conflict",trash.Result.Error);await using var db=fixture.CreateContext();Assert.False(await db.TrashOperations.AnyAsync(x=>x.AccountId==o.InternalId));Assert.Null((await Row(root.Id)).DeletedAt);Assert.Equal(2,resource=="folder"?(await Row(root.Id)).Revision:(await RecordRow(record.Id)).Revision);}
    }
