    }
    [FunctionalTheory][InlineData(false)][InlineData(true)]
    public async Task GivenRetainedFolderCascade_WhenNativeRotatingProtection_ThenRequireCompleteRetainedInventoryAndPreserveTrash(bool omit)
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var child=await Folder(s,root.Id);var record=await Record(s,child.Id);var trash=await Trash(s,root);Assert.Null(trash.Error);var all=new[]{new ContentReplacement("account",s.AccountId,1,ProfileSetup.Envelope(2)),new ContentReplacement("folder",root.PublicId,2,ProfileSetup.Envelope(2)),new ContentReplacement("folder",child.PublicId,2,ProfileSetup.Envelope(2)),new ContentReplacement("record",record.PublicId,2,ProfileSetup.Envelope(2))};var change=new ProtectionChange(s.AccountId,1,1,"rotate-content",owner.Rewrap(),omit?all[..3]:all);var raw=Bytes(change);var challenge=(await new VaultProtectionStore(fixture).ChallengeAsync(s.Actor,"change-protection",ProtocolBinary.Encode(SHA256.HashData(raw)),default)).Data!;var result=await new VaultProtectionChangeStore(fixture).ChangeAsync(new(s.Actor,s.Verifier,challenge.ChallengeId,owner.Sign(challenge),raw,change),default);Assert.Equal(omit?"validation_failed":null,result.Error);
        await using var db=fixture.CreateContext();foreach(var id in new[]{root.Id,child.Id}){var row=await db.Folders.AsNoTracking().SingleAsync(x=>x.Id==id);Assert.Equal(trash.Data!.DeletedAt,row.DeletedAt);Assert.Equal(trash.Data.PurgeAt,row.PurgeAt);Assert.Equal(omit?2:3,row.Revision);}var rr=await RecordRow(record.Id);Assert.Equal(trash.Data!.PurgeAt,rr.PurgeAt);Assert.Equal(omit?2:3,rr.Revision);Assert.Equal(3,await db.TrashEntries.CountAsync(x=>x.OperationId==db.TrashOperations.Single(o=>o.PublicId==trash.Data.TrashOperationId).Id));
